	('3f1b6a52-7c4d-4a01-9e10-11f0a6b2c403', '3f1b6a52-7c4d-4a01-9e10-11f0a6b2c303', 1, '{"root": [{"id": "about-head", "type": "core.container", "props": {"box": {"padding": {"mobile": "48px 16px", "desktop": "72px 24px"}}, "tag": "section", "layout": {"flex": {"gap": "16px", "direction": "column"}, "engine": "flex"}, "visual": {"bgColor": "#0f172a"}}, "children": [{"id": "about-head-title", "type": "core.heading", "props": {"tag": "h1", "text": "关于我们", "color": "#ffffff", "typography": {"mobile": {"fontSize": "40px", "textAlign": "center"}, "tablet": {"fontSize": "40px", "textAlign": "center"}, "desktop": {"fontSize": "40px", "textAlign": "center"}}}}, {"id": "about-head-desc", "type": "core.text", "props": {"mode": "plaintext", "text": "一支专注于内容与建站效率的产品团队。", "color": "#cbd5e1", "typography": {"mobile": {"fontSize": "16px", "textAlign": "center"}, "tablet": {"fontSize": "16px", "textAlign": "center"}, "desktop": {"fontSize": "16px", "textAlign": "center"}}}}]}, {"id": "about-story", "type": "core.container", "props": {"box": {"padding": {"mobile": "40px 16px", "desktop": "64px 24px"}}, "tag": "section", "layout": {"flex": {"gap": "16px", "direction": "column"}, "engine": "flex"}, "visual": {}}, "children": [{"id": "about-story-grid", "type": "core.container", "props": {"box": {"padding": {"mobile": "12px 0 0", "desktop": "8px 0 0"}}, "tag": "div", "layout": {"grid": {"rowGap": "32px", "columns": {"mobile": 1, "tablet": 2, "desktop": 2}, "columnGap": "32px"}, "engine": "grid"}}, "children": [{"id": "about-story-text", "type": "core.container", "props": {"tag": "div", "layout": {"flex": {"gap": "16px", "align": "flex-start", "direction": "column"}, "engine": "flex"}}, "children": [{"id": "about-story-title", "type": "core.heading", "props": {"tag": "h2", "text": "我们是谁", "color": "#0f172a", "typography": {"mobile": {}, "tablet": {}, "desktop": {"fontSize": "28px", "textAlign": "left"}}}}, {"id": "about-story-p1", "type": "core.text", "props": {"mode": "plaintext", "text"